tool_input.command:
cat >> src/receipt.test.ts <<'EOF'

test("prints a notice as the last line", () => {
  const catalog = createCatalog([
    { sku: "TASSE", name: "Espressotasse", priceCents: 1500, vat: "standard" },
  ]);
  const receipt = checkout(
    [{ sku: "TASSE", qty: 2 }],
    catalog,
    [{ code: "ZEHN50", kind: "percent", percent: 10, minSubtotalCents: 5000 }],
    "ZEHN50",
  );
  expect(renderReceipt(receipt)).toBe(
    [
      "2 x Espressotasse          CHF 30.00",
      "Total                      CHF 30.00",
      "inkl. MWST 8.1%             CHF 2.25",
      "Coupon ZEHN50 requires a minimum order of CHF 50.00",
    ].join("\n"),
  );
});
EOF
bun test 2>&1 | grep -E "fail|pass"
